n_person"},{"field":"social.instagram","value":"https://www.instagram.com/hellenicmedical.ca/","reason":"organization_social_on_person"}]},{"id":"81f05dbb-b72c-4090-8dc0-150ece239539","source_url":"https://www.hellenicmedical.ca/profile/vasiliavastis/","issues":[{"field":"photo_url","value":"https://www.hellenicmedical.ca/wp-content/uploads/2025/07/chms-default.jpg","reason":"organization_default_image_on_person"},{"field":"tagline","value":"Canadian Hellenic Medical Society","reason":"organization_name_on_person"},{"field":"social.facebook","value":"https://www.facebook.com/hellenicmedical.ca","reason":"organization_social_on_person"},{"field":"social.linkedin","value":"https://www.linkedin.com/company/hellenicmedical/","reason":"organization_social_on_person"},{"field":"social.instagram","value":"https://www.instagram.com/hellenicmedical.ca/","reason":"organization_social_on_person"}]},{"id":"80e014c0-ae7e-43b8-8d3f-8636aef3fe66","source_url":"https://www.hellenicmedical.ca/profile/vpapa/","issues":[{"field":"photo_url","value":"https://www.hellenicmedical.ca/wp-content/uploads/2025/07/chms-default.jpg","reason":"organization_default_image_on_person"},{"field":"tagline","value":"Canadian Hellenic Medical Society","reason":"organization_name_on_person"},{"field":"social.facebook","value":"https://www.facebook.com/hellenicmedical.ca","reason":"organization_social_on_person"},{"field":"social.linkedin","value":"https://www.linkedin.com/company/hellenicmedical/","reason":"organization_social_on_person"},{"field":"social.instagram","value":"https://www.instagram.com/hellenicmedical.ca/","reason":"organization_social_on_person"}]},{"id":"ba505d4e-da46-439f-b584-a2d4542eabb7","source_url":"https://www.hellenicmedical.ca/profile/vayiadalios/","issues":[{"field":"photo_url","value":"https://www.hellenicmedical.ca/wp-content/uploads/2025/07/chms-default.jpg","reason":"organization_default_image_on_person"},{"field":"tagline","value":"Canadian Hellenic Medical Society","reason":"organization_name_on_person"},{"field":"social.facebook","value":"https://www.facebook.com/hellenicmedical.ca","reason":"organization_social_on_person"},{"field":"social.linkedin","value":"https://www.linkedin.com/company/hellenicmedical/","reason":"organization_social_on_person"},{"field":"social.instagram","value":"https://www.instagram.com/hellenicmedical.ca/","reason":"organization_social_on_person"}]}]$records$::jsonb) LOOP
  SELECT profile INTO old_profile FROM zoi.listings WHERE id=(r->>'id')::uuid
   AND entity_type='professional' AND owner_workspace_id IS NULL
   AND profile#>>'{_enrich,source_url}'=r->>'source_url' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'member_repair_scope_changed:%',r->>'id';END IF;
  next_profile:=coalesce(old_profile,'{}'::jsonb);e:=coalesce(next_profile->'_enrich','{}'::jsonb);
  quarantine:=coalesce(e->'organization_identity_quarantine','[]'::jsonb);
  IF jsonb_typeof(quarantine)<>'array' THEN RAISE EXCEPTION 'member_quarantine_shape_changed';END IF;
  FOR issue IN SELECT value FROM jsonb_array_elements(r->'issues') LOOP
   path:=string_to_array(issue->>'field','.');old_value:=e#>path;
   IF old_value=issue->'value' THEN
    quarantine:=quarantine||jsonb_build_array(jsonb_build_object('field',issue->>'field','value',old_value,
     'reason',issue->>'reason','source_url',r->>'source_url','quarantined_at','2026-09-30','repair','member_identity_scope_v1'));
    e:=e#-path;removed_fields:=removed_fields+1;matched_fields:=matched_fields+1;
   ELSE RAISE EXCEPTION 'member_derived_field_changed:%:%',r->>'id',issue->>'field';END IF;
  END LOOP;
  e:=e||jsonb_build_object('organization_identity_quarantine',quarantine,'source_kind','association_member',
   'identity_scope','person','crawl_status','member_details_pending_source_review');
  -- This is provenance of the registered profile URL, not an employment/licence
  -- assertion. Organization-root committee imports get no invented relationship.
  IF r->>'source_url' ~ '^https://(www\.)?hellenicmedical\.ca/profile/[^/]+/?$' THEN
   e:=e||jsonb_build_object('source_affiliation',jsonb_build_object('listing_id',member#>>'{affiliation,listing_id}',
    'slug',member#>>'{affiliation,slug}','name','Canadian Hellenic Medical Society','entity_type','organization',
    'relationship','source_organization','source_url',r->>'source_url','method','registered_member_profile_url',
    'current_membership_verified',false));
  END IF;
  IF r->>'id'='960efee2-4bbe-467b-abb5-cacbc9a92f3b' THEN
   IF e->'member' IS NOT NULL THEN RAISE EXCEPTION 'reviewed_member_already_exists';END IF;
   e:=e||jsonb_build_object('member',member,'crawl_status','member_identity_reviewed',
    'identity_reviewed_at','2026-09-30','identity_review_method','official_indexed_profile_and_user_source_screenshot');
  END IF;
  next_profile:=jsonb_set(next_profile,'{_enrich}',e,true);
  UPDATE zoi.listings SET profile=next_profile WHERE id=(r->>'id')::uuid AND owner_workspace_id IS NULL AND profile=old_profile;
  IF NOT FOUND THEN RAISE EXCEPTION 'member_repair_concurrent_change';END IF;
  changed_rows:=changed_rows+1;
 END LOOP;
 IF changed_rows<>76 OR matched_fields<>404 THEN RAISE EXCEPTION 'member_repair_expected_scope_mismatch:%:%',changed_rows,matched_fields;END IF;
 RAISE NOTICE 'member_identity_repair rows=%, fields=%; no base fields or ownership changed',changed_rows,removed_fields;
END $repair$;
COMMIT;
